import glob
TYPE_NAMES={0:"BOOLEAN",1:"INT32",2:"INT64",3:"INT96",4:"FLOAT",5:"DOUBLE",6:"BYTE_ARRAY",7:"FIXED_LEN_BYTE_ARRAY"}
ENC_NAMES={0:"PLAIN",1:"GROUP_VAR_INT",2:"PLAIN_DICTIONARY",3:"RLE",4:"BIT_PACKED",5:"DELTA_BINARY_PACKED",6:"DELTA_LENGTH_BYTE_ARRAY",7:"DELTA_BYTE_ARRAY",8:"RLE_DICTIONARY",9:"DELTA_CC",10:"BYTE_STREAM_SPLIT"}
CODEC_NAMES={0:"UNCOMPRESSED",1:"SNAPPY",2:"GZIP",3:"LZO",4:"BROTLI",5:"LZ4",6:"ZSTD",7:"LZ4_RAW"}

for fname in sorted(glob.glob("assets/*.parquet*")):
    try:
        data=open(fname,'rb').read()
        if data[-4:]!=b'PAR1':
            print(f"{fname}: not PAR1 magic {data[-4:]}")
            continue
        flen=int.from_bytes(data[-8:-4],'little')
        footer=data[len(data)-8-flen:len(data)-8]
        res,_=decode_struct(footer,0)
        rgs = res[4][1]  # list of dicts
        codecs=set()
        encs=set()
        for rg in rgs:
            # rg is dict {1:(9,cols),2:...,3:...}
            cols = rg[1][1]
            for col in cols:
                meta = col[3][1]  # field 3 struct
                # codec field 4, encodings field 2
                codec = meta.get(4, (None,None))[1]
                enc_list = meta.get(2, (None,[]))[1]
                codecs.add(codec)
                for e in enc_list:
                    encs.add(e)
        print(f"{fname}: codecs={sorted(codecs)} encs={sorted(encs)} rows={res[3][1]} rgs={len(rgs)}")
    except Exception as e:
        import traceback
        print(fname, "ERR", e)
        traceback.print_exc()
        break
