# ================= Thrift compact decoder =================
def _read_varint(buf, pos):
    shift = 0
    result = 0
    while True:
        b = buf[pos]; pos += 1
        result |= (b & 0x7F) << shift
        if (b & 0x80) == 0:
            break
        shift += 7
    return result, pos

def _zigzag_to_int(n):
    return (n >> 1) ^ -(n & 1)

def _decode_value(buf, pos, ctype):
    if ctype == 1:
        return True, pos
    elif ctype == 2:
        return False, pos
    elif ctype == 3:
        v = buf[pos]; pos += 1
        if v >= 128: v -= 256
        return v, pos
    elif ctype in (4,5,6):
        n, pos2 = _read_varint(buf, pos)
        return _zigzag_to_int(n), pos2
    elif ctype == 7:
        import struct
        v = struct.unpack_from('<d', buf, pos)[0]
        return v, pos+8
    elif ctype == 8:
        n, pos2 = _read_varint(buf, pos)
        v = bytes(buf[pos2:pos2+n])
        return v, pos2+n
    elif ctype in (9,10):
        b = buf[pos]; pos += 1
        size = (b >> 4) & 0x0F
        elem_type = b & 0x0F
        if size == 15:
            size, pos = _read_varint(buf, pos)
        lst = []
        for _ in range(size):
            v, pos = _decode_value(buf, pos, elem_type)
            lst.append(v)
        return lst, pos
    elif ctype == 11:
        size, pos2 = _read_varint(buf, pos)
        pos = pos2
        if size == 0:
            return {}, pos
        b = buf[pos]; pos += 1
        ktype = (b >> 4) & 0x0F
        vtype = b & 0x0F
        d = {}
        for _ in range(size):
            k, pos = _decode_value(buf, pos, ktype)
            v, pos = _decode_value(buf, pos, vtype)
            try:
                d[k] = v
            except:
                d[repr(k)] = v
        return d, pos
    elif ctype == 12:
        return _decode_struct(buf, pos)
    else:
        raise ValueError(f"unknown ctype {ctype}")

def _decode_struct(buf, pos):
    result = {}
    last_fid = 0
    while True:
        if pos >= len(buf):
