class ParquetError(Exception):
    pass

class ParquetFile:
    def __init__(self, path):
        self.path = path
        with open(path, 'rb') as f:
            self.data = f.read()
        if len(self.data) < 12:
            raise ParquetError("Parquet error: Invalid Parquet file. Corrupt footer")
        if self.data[0:4] != b'PAR1':
            # check encrypted magic PARE?
            if self.data[-4:] == b'PARE':
                raise ParquetError("Parquet error: Parquet file has an encrypted footer but the encryption feature is disabled")
            raise ParquetError("Parquet error: Invalid Parquet file. Corrupt footer")
        magic = self.data[-4:]
        if magic == b'PARE':
            raise ParquetError("Parquet error: Parquet file has an encrypted footer but the encryption feature is disabled")
        if magic != b'PAR1':
            raise ParquetError("Parquet error: Invalid Parquet file. Corrupt footer")
        try:
            flen = int.from_bytes(self.data[-8:-4], 'little')
        except Exception:
            raise ParquetError("Parquet error: Invalid Parquet file. Corrupt footer")
        if flen < 0 or flen > len(self.data) - 12:
            raise ParquetError("Parquet error: Invalid Parquet file. Corrupt footer")
        footer_bytes = self.data[len(self.data)-8-flen:len(self.data)-8]
        try:
            res, pos = thrift_decode_struct(footer_bytes, 0)
        except Exception as e:
            raise ParquetError("Parquet error: Invalid Parquet file. Corrupt footer")
        # res is dict fid -> (ctype, val)
        try:
            self.version = res[1][1]
            self.schema_raw = res[2][1]
            self.num_rows = res[3][1]
            self.row_groups_raw = res[4][1]
            kv = res.get(5, (None, []))[1] if 5 in res else []
            self.key_value = kv
            self.created_by = None
            if 6 in res:
                v = res[6][1]
                if isinstance(v, bytes):
                    try:
                        self.created_by = v.decode('utf-8', errors='replace')
                    except Exception:
                        self.created_by = str(v)
                else:
                    self.created_by = str(v)
        except KeyError as e:
            raise ParquetError("Parquet error: Invalid Parquet file. Corrupt footer")
        except ParquetError:
            raise
        except Exception as e:
            raise ParquetError("Parquet error: Invalid Parquet file. Corrupt footer")
        # Validate parquet types: check for invalid type like -7 (PARQUET-1481 file)
        # That file has schema with type -7? Our decoder would have decoded type as zigzag? -7 would be encoded as? Let's check: type -7 zigzag = 13? Our decoder would give -7? Actually _zigzag_to_int(13) = (13>>1)^-(13&1)=6^-1 = -7. Yes. So we need to detect invalid physical types and raise "unexpected parquet type: -7"
        for elem in self.schema_raw:
            if 1 in elem:
                t = elem[1][1]
                if t not in TYPE_NAMES:
                    raise ParquetError("Parquet error: unexpected parquet type: {}".format(t))
        # Check for specific malformed files that polars reports with "parquet: File out of specification: ..."
