            if 3 in elem:
                e['repetition'] = elem[3][1]
            else:
                e['repetition'] = None
            if 4 in elem:
                v = elem[4][1]
                if isinstance(v, bytes):
                    try:
                        e['name'] = v.decode('utf-8', errors='replace')
                    except Exception:
                        e['name'] = str(v)
                else:
                    e['name'] = str(v)
            else:
                e['name'] = ""
            if 5 in elem:
                e['num_children'] = elem[5][1]
            else:
                e['num_children'] = None
            if 6 in elem:
                e['converted'] = elem[6][1]
            else:
                e['converted'] = None
            if 7 in elem:
                e['scale'] = elem[7][1]
            else:
                e['scale'] = None
            if 8 in elem:
                e['precision'] = elem[8][1]
            else:
                e['precision'] = None
            if 9 in elem:
                e['field_id'] = elem[9][1]
            else:
                e['field_id'] = None
            if 10 in elem:
                # logicalType is struct, keep raw
                e['logical'] = elem[10][1]
            else:
                e['logical'] = None
            self.schema.append(e)
        # Build tree: schema[0] is root. Use num_children to build hierarchy.
        # Also compute max definition/repetition levels for each leaf, and leaf list
        # First, build nodes with children indices
        self.nodes = []  # list of dict with elem, children, parent, depth, etc.
        for i, e in enumerate(self.schema):
            self.nodes.append({'elem': e, 'children': [], 'parent': None, 'index': i})
        # Use stack: root has num_children, then subsequent elements are its children recursively
        # Standard parquet schema flat list is depth-first pre-order.
        # We can build by iterating with a stack of (node, remaining_children)
        if len(self.nodes) == 0:
            return
        # root
        stack = [(0, self.schema[0].get('num_children') or 0)]
        # parent for next nodes? Actually we need to assign parents
        # Iterate i from 1..n-1
        for i in range(1, len(self.nodes)):
            # pop stack until top has remaining >0
            while stack and stack[-1][1] == 0:
                stack.pop()
            if not stack:
                break
            parent_idx, rem = stack[-1]
            # assign parent
            self.nodes[i]['parent'] = parent_idx
            self.nodes[parent_idx]['children'].append(i)
            # decrement parent remaining
            stack[-1] = (parent_idx, rem - 1)
            # if this node has children, push it
            nc = self.schema[i].get('num_children')
            if nc is not None and nc > 0:
                stack.append((i, nc))
        # Compute leaves: nodes with type != None (physical type present)
        self.leaves = []
        for i, n in enumerate(self.nodes):
            if n['elem']['type'] is not None:
                self.leaves.append(i)
        # For each leaf, compute max_rep, max_def by walking to root counting REPEATED/OPTIONAL
        self.leaf_max_rep = {}
        self.leaf_max_def = {}
        for leaf_idx in self.leaves:
            max_rep = 0
            max_def = 0
            cur = leaf_idx
            # include leaf's own repetition? Actually leaf's repetition contributes, plus ancestors (excluding root which has no repetition)
            while cur is not None and cur != 0:
                rep = self.nodes[cur]['elem'].get('repetition')
                if rep == 2:  # REPEATED
                    max_rep += 1
                    max_def += 1
                elif rep == 1:  # OPTIONAL
                    max_def += 1
                # REQUIRED adds nothing
                cur = self.nodes[cur]['parent']
            self.leaf_max_rep[leaf_idx] = max_rep
            self.leaf_max_def[leaf_idx] = max_def
        # Build display tree lines for schema view (with prefixes)
        self._build_tree_lines()

