# ================= Decompression =================
def decompress_snappy(data):
    # Parquet SNAPPY: raw snappy block (without framing) with 4-byte LE length? Actually need to handle both.
    # Try to detect: if first 4 bytes LE == len(data)-4? Or uncompressed length?
    # For now, implement raw snappy decompress and try with/without 4-byte prefix.
    # First, try stripping 4-byte prefix if present (parquet-mr style: 4-byte length prefix?)
    # Observed: for snappy files, compressed size includes prefix? Let's handle generically:
    # If data starts with varint? No.
    # Simplest: try raw decompress on data, if fails try data[4:].
    # Also need to handle snappy framing (with stream identifier)? Parquet uses raw block, not framing.
    try:
        return snappy_decompress_raw(data)
    except Exception:
        pass
    # try skipping 4 bytes (length prefix)
    if len(data) > 4:
        try:
            return snappy_decompress_raw(data[4:])
        except Exception:
            pass
    # try with length prefix included? Some implementations store uncompressed length as varint?
    raise ParquetError("parquet: snappy decompress failed")

def snappy_decompress_raw(data):
    # Pure python snappy decompress (raw block, no framing)
    # Spec: first varint is uncompressed length, then elements: literal or copy
    pos = 0
    # read uncompressed length as varint (LEB128, little endian base128)
    n = 0
    shift = 0
    while True:
        if pos >= len(data):
            raise ValueError("truncated snappy length")
        b = data[pos]
        pos += 1
        n |= (b & 0x7F) << shift
        if (b & 0x80) == 0:
            break
        shift += 7
        if shift >= 32:
            raise ValueError("snappy length too large")
    out = bytearray(n)
    out_pos = 0
    while out_pos < n:
        if pos >= len(data):
            raise ValueError("truncated snappy")
        b = data[pos]
        pos += 1
        tag = b & 0x03
        if tag == 0:
            # literal: (b>>2) +1? Actually if (b>>2) <60, length = (b>>2)+1, else extra bytes
            length = b >> 2
            if length < 60:
                length += 1
            else:
                extra = length - 59  # 1..4 bytes
                if pos + extra > len(data):
                    raise ValueError("truncated literal length")
                length = 0
                for i in range(extra):
                    length |= data[pos+i] << (8*i)
                pos += extra
                length += 1
            if pos + length > len(data) or out_pos + length > n:
                raise ValueError("literal out of bounds")
            out[out_pos:out_pos+length] = data[pos:pos+length]
            pos += length
            out_pos += length
        elif tag == 1:
            # copy with 1-byte offset: length = ((b>>2)&0x7)+4, offset = ((b>>5)<<8)|data[pos]
            length = ((b >> 2) & 0x07) + 4
            if pos >= len(data):
                raise ValueError("truncated copy1")
            offset = ((b >> 5) << 8) | data[pos]
            pos += 1
            if offset == 0 or offset > out_pos:
                raise ValueError("invalid offset")
            for i in range(length):
                if out_pos >= n:
                    raise ValueError("copy overflow")
                out[out_pos] = out[out_pos - offset]
                out_pos += 1
        elif tag == 2:
            # copy with 2-byte offset: length = (b>>2)+1, offset = LE16
            length = (b >> 2) + 1
            if pos + 2 > len(data):
                raise ValueError("truncated copy2")
            offset = data[pos] | (data[pos+1] << 8)
            pos += 2
            if offset == 0 or offset > out_pos:
                raise ValueError("invalid offset2")
            for i in range(length):
                if out_pos >= n:
                    raise ValueError("copy2 overflow")
                out[out_pos] = out[out_pos - offset]
                out_pos += 1
        else:  # tag == 3
            # copy with 4-byte offset: length = (b>>2)+1, offset = LE32
            length = (b >> 2) + 1
            if pos + 4 > len(data):
                raise ValueError("truncated copy4")
            offset = data[pos] | (data[pos+1] << 8) | (data[pos+2] << 16) | (data[pos+3] << 24)
            pos += 4
            if offset == 0 or offset > out_pos:
                raise ValueError("invalid offset4")
            for i in range(length):
                if out_pos >= n:
                    raise ValueError("copy4 overflow")
                out[out_pos] = out[out_pos - offset]
                out_pos += 1
    return bytes(out)

def decompress_gzip(data):
    import gzip
    return gzip.decompress(data)

def decompress_zstd(data, uncompressed_size=None):
    import ctypes, ctypes.util
    try:
        lib = ctypes.CDLL("libzstd.so.1")
    except Exception:
        try:
            lib = ctypes.CDLL("libzstd.so")
        except Exception as e:
            raise ParquetError("zstd not available")
    # ZSTD_decompress
    lib.ZSTD_decompress.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_void_p, ctypes.c_size_t]
    lib.ZSTD_decompress.restype = ctypes.c_size_t
    lib.ZSTD_isError.argtypes = [ctypes.c_size_t]
    lib.ZSTD_isError.restype = ctypes.c_uint
    # estimate size: use provided uncompressed_size or get frame content size
    if uncompressed_size is None:
        # try get frame content size
        lib.ZSTD_getFrameContentSize.argtypes = [ctypes.c_void_p, ctypes.c_size_t]
